	t.Run("hearth.lock/v1", func(t *testing.T) {
		entity := Entity{ID: EntityID("generated_lockv1"), TypeID: EntityTypeLockV1, Support: EntitySupport("{\"state\":{},\"operations\":{\"set\":{}}}")}
		if stateless, err := catalog.IsStateless(entity.TypeID); err != nil || stateless != false {
			t.Errorf("catalog stateless = %v, %v, want false", stateless, err)
		}
		normalizedSupport, err := catalog.NormalizeSupport(entity.TypeID, entity.Support)
		if err != nil {
			t.Fatalf("catalog support: %v", err)
		}
		if !entitytypetest.EqualJSON(t, normalizedSupport, []byte("{\"state\":{},\"operations\":{\"set\":{}}}")) {
			t.Errorf("catalog normalized support = %s, want %s", normalizedSupport, "{\"state\":{},\"operations\":{\"set\":{}}}")
		}
		normalizedState, err := catalog.NormalizeState(entity, Value("\"locked\""))
		if err != nil {
			t.Fatalf("catalog State: %v", err)
		}
		if !entitytypetest.EqualJSON(t, normalizedState, []byte("\"locked\"")) {
			t.Errorf("catalog normalized State = %s, want %s", normalizedState, "\"locked\"")
		}
		resolvedSet, err := catalog.ResolveCommand(entity, OperationName("set"), CommandParameters("{\"value\":\"locked\"}"))
		if err != nil {
			t.Fatalf("catalog resolve set: %v", err)
		}
		if !entitytypetest.EqualJSON(t, resolvedSet.Parameters, []byte("{\"value\":\"locked\"}")) {
			t.Errorf("catalog normalized set parameters = %s, want %s", resolvedSet.Parameters, "{\"value\":\"locked\"}")
		}
		if resolvedSet.Deadline != 30000*time.Millisecond {
			t.Errorf("catalog set deadline = %v, want %v", resolvedSet.Deadline, 30000*time.Millisecond)
		}
		if resolvedSet.Outcome != OutcomeObserved {
			t.Errorf("catalog set outcome = %v, want %v", resolvedSet.Outcome, OutcomeObserved)
		}
		if satisfied, err := catalog.Satisfies(entity, CommandRecord{OperationName: OperationName("set"), Parameters: CommandParameters("{\"value\":\"locked\"}")}, Value("\"locked\"")); err != nil || !satisfied {
			t.Errorf("catalog set satisfied outcome = %v, %v", satisfied, err)
		}
		if satisfied, err := catalog.Satisfies(entity, CommandRecord{OperationName: OperationName("set"), Parameters: CommandParameters("{\"value\":\"locked\"}")}, Value("\"unlocked\"")); err != nil || satisfied {
			t.Errorf("catalog set unsatisfied outcome = %v, %v", satisfied, err)
		}
		if equal, err := catalog.EqualState(entity, Value("\"locked\""), Value("\"locked\"")); err != nil || !equal {
			t.Errorf("catalog equal State = %v, %v", equal, err)
		}
		if equal, err := catalog.EqualState(entity, Value("\"unlocked\""), Value("\"locked\"")); err != nil || equal {
			t.Errorf("catalog unequal State = %v, %v", equal, err)
		}
		if supported, err := catalog.SupportsEntityEvent(entity, EntityEventName("single_press")); err != nil || supported {
			t.Errorf("catalog non-event type accepted an Entity Event: %v, %v", supported, err)
		}
		malformedNonEventEntity := Entity{ID: EntityID("generated_lockv1"), TypeID: EntityTypeLockV1, Support: EntitySupport("[]")}
		if supported, err := catalog.SupportsEntityEvent(malformedNonEventEntity, EntityEventName("single_press")); err != nil || supported {
			t.Errorf("catalog non-event type with malformed support accepted an Entity Event: %v, %v", supported, err)
		}
		if _, err := catalog.NormalizeSupport(entity.TypeID, EntitySupport("{\"events\":{\"names\":[\"single_press\"]},\"operations\":{\"set\":{}},\"state\":{}}")); err == nil {
			t.Error("catalog accepted event support for a closed type")
		}
	})
